var n=`0842-medu-vada`;var a=`world-0842`;var t=`IN`;var s=`south-asia`;var r=8;var d=522;var o={en:`Medu Vada`,ua:`Меду вада`};var u={en:`Medu Vada is a India dish made with urad dal, serrano pepper, desiccated coconut, plain yogurt. This home-scale recipe assigns measured ingredients to the steps where they are used. Homemade coconut–yogurt accompaniment instead of prepared chutney.`,ua:`Меду вада, страва кухні країни Індія. Основні складники: урід дал, перець серрано, кокосова стружка, натуральний йогурт. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів. Домашня кокосово-йогуртова добавка замість готового чатні.`};var g=[{en:`Soak the listed rice, grains or noodles in clean water for about 480 minutes as appropriate, then drain; grind rice and urad for batter if required by this dish.`,ua:`Замочіть зазначені рис, крупи або локшину у чистій воді приблизно на 480 хвилин залежно від продукту, потім злийте; для тіста за потреби подрібніть рис і урад.`,t:[`soaking-legumes`],m:480,i:[[`urad-dal`,360,`g`],[`water`,1e3,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:13,i:[[`ground-ginger`,15,`g`],[`serrano-pepper`,2,`pcs`],[`cumin-seeds`,5,`g`],[`table-salt`,6,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:10,i:[]},{en:`Shape soaked-ground urad batter into rings with holes and fry in batches until golden, crisp outside and cooked within.`,ua:`Сформуйте з подрібненого ураду кільця з отворами й обсмажте партіями до золотавої хрусткої скоринки та готової серединки.`,t:[`deep-frying`],m:17,i:[[`canola-oil`,750,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`desiccated-coconut`,90,`g`],[`plain-yogurt`,70,`g`]]}];var l={slug:n,id:a,country:`IN`,region:s,servings:8,minutes:522,title:o,text:u,steps:g};export{t as country,l as default,a as id,d as minutes,s as region,r as servings,n as slug,g as steps,u as text,o as title};